/*************************************** pageNav.js 함수들  Start *********************************************/

// 페이지 이동 [1] [2] ... 하는 HTML 코드를 생성해서 돌려준다.
//	funcName : 실제 페이지 이동을 위한 함수이름 (예: gotoPage)
//	pageNum : 현재 페이지 번호
//	pageSize : 한 페이지당 결과 갯수
//	total : 전체 결과 갯수
/**
 * @method
 * @name pageNav
 * @description desc
 * @param {string} funcName desc
 * @param {string} pageNum desc
 * @param {string} pageSize desc
 * @param {string} total desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.pageNav = function(funcName, pageNum, pageSize, total) {
    //alert("funcName : " + funcName + " : pageNum : " + pageNum + " : pageSize : " + pageSize + " : total : " + total);
    if (total < 1) return "";
    var ret = "";
    var PAGEBLOCK = 10;
    var totalPages = Math.floor((total - 1) / pageSize) + 1;
    var firstPage = Math.floor((pageNum - 1) / PAGEBLOCK) * PAGEBLOCK + 1;
    if (firstPage <= 0) // ?
        firstPage = 1;
    var lastPage = firstPage - 1 + PAGEBLOCK;
    if (lastPage > totalPages) lastPage = totalPages;
    if (firstPage > PAGEBLOCK) {
        ret += scwin.navAnchor(funcName, 1, "<<처음") + "&nbsp;\n";
        ret += scwin.navAnchor(funcName, (firstPage - 1), "<이전") + "&nbsp;\n";
        //		ret += navAnchor(funcName, firstPage-1, "<IMG SRC=\"/images/proc9/ar_left.gif\" width='14' height='13' border='0' align='absmiddle'>") + "&nbsp;\n";

    }
    for (i = firstPage; i <= lastPage; i++) {
        if (pageNum == i) ret += "<b>[" + i + "]</b>&nbsp;\n";

        else ret += scwin.navAnchor(funcName, i, "[" + i + "]") + "&nbsp;\n";
    }
    if (lastPage < totalPages) {
        ret += scwin.navAnchor(funcName, (lastPage + 1), "다음>") + "&nbsp;\n";
        ret += "&nbsp;" + scwin.navAnchor(funcName, totalPages, "끝>>") + "\n";
        //		ret += "&nbsp;" + navAnchor(funcName, lastPage+1, "<IMG SRC=\"/images/proc9/ar_right.gif\" width='14' height='13' border='0' align='absmiddle'>") + "\n";		

    }
    return ret;
};
/**
 * @method
 * @name navAnchor
 * @description desc
 * @param {string} funcName desc
 * @param {string} pageNo desc
 * @param {string} anchorText desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.navAnchor = function(funcName, pageNo, anchorText) {
    return "<a href='javascript:" + funcName + "(" + pageNo + ")' class='menugray'>" + anchorText + "</a>";
};




// 페이지 이동 [1] [2] ... 하는 HTML 코드를 생성해서 돌려준다.
//	funcName : 실제 페이지 이동을 위한 함수이름 (예: gotoPage)
//	pageNum : 현재 페이지 번호
//	pageSize : 한 페이지당 결과 갯수
//	total : 전체 결과 갯수
//	firstImg : 처음 이미지 <img src=\"~>
//	lastImg : 마지막 이미지 <img src=\"~>
//	prevImg : 처음 이미지 <img src=\"~>
//	nextImg : 마지막 이미지 <img src=\"~>
//	midTagSrt : 현재 페이지의 style 정의 start(<font color=~>)
//	midTagEnd : 현재 페이지의 style 정의 end (</font>)
//	separate :  페이지 번호간 구분문자 or IMG
/**
 * @method
 * @name pageNav2
 * @description desc
 * @param {string} funcName desc
 * @param {string} pageNum desc
 * @param {string} pageSize desc
 * @param {string} total desc
 * @param {string} firstImg desc
 * @param {string} lastImg desc
 * @param {string} prevImg desc
 * @param {string} nextImg desc
 * @param {string} midTagSrt desc
 * @param {string} midTagEnd desc
 * @param {string} separate desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.pageNav2 = function(funcName, pageNum, pageSize, total, firstImg, lastImg, prevImg, nextImg, midTagSrt, midTagEnd, separate) {
    if (total < 1) return "";
    if (firstImg == "") firstImg = "<<처음";
    if (lastImg == "") lastImg = "끝>>";
    var ret = "";
    var PAGEBLOCK = 10;
    var totalPages = Math.floor((total - 1) / pageSize) + 1;
    var firstPage = Math.floor((pageNum - 1) / PAGEBLOCK) * PAGEBLOCK + 1;
    if (firstPage <= 0) // ?
        firstPage = 1;
    var lastPage = firstPage - 1 + PAGEBLOCK;
    if (lastPage > totalPages) lastPage = totalPages;
    if (firstPage > PAGEBLOCK) {
        ret += scwin.navAnchor(funcName, 1, firstImg) + "&nbsp;\n";
        ret += scwin.navAnchor(funcName, (firstPage - 1), prevImg) + "&nbsp;\n";
    }
    for (i = firstPage; i <= lastPage; i++) {
        if (i > firstPage) ret += separate + "&nbsp;\n";
        if (pageNum == i) ret += midTagSrt + i + midTagEnd + "&nbsp;\n";

        else ret += scwin.navAnchor(funcName, i, i) + "&nbsp;\n";
    }
    if (lastPage < totalPages) {
        ret += scwin.navAnchor(funcName, (lastPage + 1), nextImg) + "&nbsp;\n";
        ret += "&nbsp;" + scwin.navAnchor(funcName, totalPages, lastImg) + "\n";
    }
    return ret;
};


/*************************************** pageNav.js 함수들  End ****************************************************/

/*************************************** codeRelate.js 함수들  Start **************************************************/
jr = new Array(); // 종목코드 search
