/**
 * jcode.js에서 호출하는 함수.
 * @param jtt     종목명의 첫글자
 * @param jcode 종목코드
 * @param jname 종목명
 * @param jtype   종목유형 (1:일반, 2: 벤처, 3:MF)
 * @param jtype2 종목유형2 (G:관리,K:감리,M:매매거래정지,T:투자유의,B:불성실,J:정상)
 */
/**
 * @method
 * @name jongObj
 * @description desc
 * @param {string} jtt desc
 * @param {string} jcode desc
 * @param {string} jname desc
 * @param {string} jtype desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.jongObj = function(jtt, jcode, jname, jtype) {
    this.jtt = jtt;
    this.jcode = jcode;
    this.jname = jname;
    this.jtype = jtype;
};


/**
 * 해당 종목코드가 존재하는 코드인지 jcode.js에서 체크한다.
 * @param jcode 종목코드
 * @return boolFind  존재하면 1을 리턴한다.
 */
/**
 * @method
 * @name findcode
 * @description desc
 * @param {string} jcode desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.findcode = function(jcode) {
    scwin.boolFind = 0;
    for (var j = 0; j < jr.length; j++) {
        if (jr[j].jcode == jcode) {
            scwin.findJcode = jr[j].jcode;
            scwin.findJname = jr[j].jname;
            scwin.boolFind = 1;
            break;
        }
    }
};
/**
 * @method
 * @name getCodeSearchName
 * @description desc
 * @param {string} jcode desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.getCodeSearchName = function(jcode) {
    for (var j = 0; j < jr.length; j++) {
        if (jr[j].jcode == jcode) {
            scwin.findJname = jr[j].jname;
            break;
        }
    }
    return scwin.findJname;
};
/**
 * @method
 * @name findcodeNew
 * @description desc
 * @param {string} jcode desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.findcodeNew = function(jcode) {
    for (var j = 0; j < jr.length; j++) {
        if (jr[j].jcode == jcode) {
            return jr[j].jcode + "|" + jr[j].jname;
            break;
        }
    }
    return false;
};
/**
 * @method
 * @name getCodeName
 * @description desc
 * @param {string} jcode desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.getCodeName = function(jcode) {
    for (var j = 0; j < jr.length; j++) {
        if (jr[j].jcode == jcode && jr[j].jname.indexOf("변경전사명") < 1) {
            return jr[j].jname;
            breakl;
        }
    }
    return false;
};


/**
 * 해당 종목명이 존재하는지 jcode.js에서 체크한다.
 * @param jcode 종목명
 * @return boolFind  존재하면 1을 리턴한다.
 */
/**
 * @method
 * @name findcodeName
 * @description desc
 * @param {string} codename desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.findcodeName = function(codename) {
    scwin.boolFind = 0;
    var inputLength = codename.length;
    for (var j = 0; j < jr.length; j++) {
        if (jr[j].jname.substring(0, inputLength).toUpperCase() == codename) {
            scwin.findJcode = jr[j].jcode;
            scwin.findJname = jr[j].jname;
            scwin.boolFind = 1;
            break;
        }
    }
};
/**
 * @method
 * @name findcodeNameNew
 * @description desc
 * @param {string} codename desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.findcodeNameNew = function(codename) {
    var inputLength = codename.length;
    for (var j = 0; j < jr.length; j++) {
        if (jr[j].jname.substring(0, inputLength).toUpperCase() == codename) {
            return jr[j].jcode + "|" + jr[j].jname;
            break;
        }
    }
    return false;
};


/**
 * 문자열이 숫자로만 되어있는지 check하는 함수
 * @param myString 숫자인지 체크할 스트링
 * @return flag 숫자인 경우 true 리턴
 */
/**
 * @method
 * @name isDigit
 * @description desc
 * @param {string} myString desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.isDigit = function(myString) {
    var flag = true;
    for (var i = 0; i < myString.length; i++) {
        if (myString.charCodeAt(i) < 48 || myString.charCodeAt(i) > 57) {
            flag = false;
            break;
        }
    }
    return flag;
};


