/**
 * @method
 * @name setPeriod
 * @description desc
 * @param {string} a desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.setPeriod = function(a) {
    var dat = new Date();
    var dat2 = new Date();
    var pyear = dat.getYear();
    var pmonth = dat.getMonth() + 1;
    var pday = dat.getDate();


    // 일자 * 시간 * 분 * 초 * 밀리세컨
    // 3개월
    if (a == '3') {
        dat2 = scwin.addMonth(pyear, pmonth, pday, -3);
        var year = dat2.getYear();
        var month = dat2.getMonth() + 1;
        var day = dat2.getDate();

        // 6개월
    } else if (a == '6') {
        dat2 = scwin.addMonth(pyear, pmonth, pday, -6);
        var year = dat2.getYear();
        var month = dat2.getMonth() + 1;
        var day = dat2.getDate();

        //1년
    } else if (a == '12') {
        var year = dat2.getYear() - 1;
        var month = dat2.getMonth() + 1;
        var day = dat2.getDate();
        //3년
    } else if (a == '36') {
        var year = dat2.getYear() - 3;
        var month = dat2.getMonth() + 1;
        var day = dat2.getDate();
        //5년
    } else if (a == '60') {
        var year = dat2.getYear() - 5;
        var month = dat2.getMonth() + 1;
        var day = dat2.getDate();
    } else {

    }
    if (month < 10) month = '0' + month;
    if (day < 10) day = '0' + day;
    if (pmonth < 10) pmonth = '0' + pmonth;
    if (pday < 10) pday = '0' + pday;
    document.form.strDate.setValue(year + '' + month + '' + day);
    document.form.endDate.setValue(pyear + '' + pmonth + '' + pday);
};


/**/
/**
 * @method
 * @name addMonth
 * @description desc
 * @param {string} yyyy desc
 * @param {string} mm desc
 * @param {string} dd desc
 * @param {string} pMonth desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.addMonth = function(yyyy, mm, dd, pMonth) {
    // 년, 월, 일, 계산할 월 (년도는 반드시 4자리로 입력)
    var cDate; // 계산에 사용할 날짜 객체 선언
    var oDate; // 리턴할 날짜 객체 선언
    var cYear, cMonth, cDay; // 계산된 날짜값이 할당될 변수
    mm = mm * 1 + ((pMonth * 1) - 1); // 월은 0~11 이므로 하나 빼준다
    cDate = new Date(yyyy, mm, dd); // 계산된 날짜 객체 생성 (객체에서 자동 계산)
    cYear = cDate.getFullYear(); // 계산된 년도 할당
    cMonth = cDate.getMonth(); // 계산된 월 할당
    cDay = cDate.getDate(); // 계산된 일자 할당
    oDate = (dd == cDay) ? cDate : new Date(cYear, cMonth, 0); // 넘어간 월의 첫쨋날 에서 하루를 뺀 날짜 객체를 생성한다.
    return oDate;
};


