/**
 * 종목코드 입력시 종목명을 검색해 Set해준다.
 */
/**
 * @method
 * @name beforefindCode
 * @description desc
 * @param {string} flag desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.beforefindCode = function(flag) {
    var f = document.frm;
    var code = document.form.comCode.getValue();
    var boolDigit = scwin.isDigit(code);
    var cnt = "";
    if (!boolDigit) {
        frm.isNum.setValue("false");
        if (code.substring(0, 1) == 'A' && scwin.isDigit(code.substring(1))) {
            code = code.substring(1);
            frm.isNum.setValue("true");
        }
    } else {
        if (code.length != 6 && code.length != 0) {
            alert("종목코드 자리 수는 6자리 입니다.");
            document.form.comCode.setValue("");
            return;
        }
        frm.isNum.setValue("true");
    }
    var param = "";
    if (flag == 'read') frm.flag.setValue('read');

    else frm.flag.setValue('');
    frm.target = "REGULAR";
    frm.code.setValue(code);
    frm.action = "/person/findCode.jsp";
    frm.submit();
};


/**
 * 코드검색시 이전회사명인지 여부를 판단한다. 
 */
/**
 * @method
 * @name changeFlag
 * @description desc
 * @param {string} code desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.changeFlag = function(code) {
    var flag = "false";
    for (var j = 0; j < jr.length; j++) {
        if (code == jr[j].jname.substring(0, code.length)) {
            if (jr[j].jname.indexOf("변경전사명") > 0) {
                flag = "true";
                break;
            }
        }
    }
    return flag;
};


/**
 * 조회값의 같은 회사명 수 를 구한다.(코드값과 회사명도 같이 넘겨준다.)
 */
/**
 * @method
 * @name getSameNameCnt
 * @description desc
 * @param {string} value desc
 * @param {string} isNum desc
 * @param {string} regcncl desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.getSameNameCnt = function(value, isNum, regcncl) {
    var cnt = 0;
    var code = "";
    var name = "";
    if (isNum) {
        for (var j = 0; j < jr.length; j++) {
            if (value == jr[j].jcode.substring(0, value.length)) {
                if (jr[j].jname.indexOf("변경전사명") < 1) {
                    if (regcncl == "1") {
                        code = jr[j].jcode;
                        name = jr[j].jname;
                        cnt++;
                        break;
                    } else {
                        if (jr[j].jname.indexOf("폐지") < 1) {
                            code = jr[j].jcode;
                            name = jr[j].jname;
                            cnt++;
                            break;
                        }
                    }
                }
            }
        }
    } else {
        for (var j = 0; j < jr.length; j++) {
            if (value == jr[j].jname.substring(0, value.length)) {
                if (regcncl == "1") {
                    code = jr[j].jcode;
                    name = jr[j].jname;
                    cnt++;
                } else {
                    if (jr[j].jname.indexOf("폐지") < 1) {
                        code = jr[j].jcode;
                        name = jr[j].jname;
                        cnt++;
                    }
                }
            }
        }
    }
    var data = new Array();
    data[0] = cnt;
    data[1] = code;
    data[2] = name;
    return data;
};


/**
 * 종목코드 입력시 종목명을 검색해 Set해준다.
 */
/**
 * @method
 * @name searchCode
 * @description desc
 * @param {string} flag desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.searchCode = function(flag) {
    var f = document.form;
    var code = document.form.comCode.getValue();
    var regcncl = "";
    if (document.form.regcncl[1].checked) regcncl = "1";
    if (code.charAt(0) == 'A' && code.length == 7 && scwin.isDigit(code.substring(1))) code = code.substring(1);
    var cnt = "";
    var data = new Array();
    var changeNameFlag = "false";
    var isNum = scwin.isDigit(code);
    if (isNum) {
        if (code.length != 6 && code.length != 0) {
            alert("종목코드 자리 수는 6자리 입니다.");
            document.form.comCode.setValue("");
            return;
        }
    } else {
        changeNameFlag = scwin.changeFlag(code);
    }
    data = scwin.getSameNameCnt(code, isNum, regcncl);
    cnt = parseInt(data[0]);
    if (cnt == 0) {
        alert("종목  검색결과가 없습니다.");
        document.form.comCode.setValue("");
        document.form.beforeName.setValue("");
        return;
    } else if (cnt == 1) {
        document.form.comCode.setValue(data[1]);
        if (data[2].indexOf("변경전사명") > 1) {
            document.form.comName.setValue(scwin.getCodeName(data[1]));
            document.form.beforeName.setValue(data[2]);
            self.before.innerHTML = data[2];
        } else {
            document.form.comName.setValue(data[2]);
            if (flag == 'read') document.form.beforeName.setValue("");
            self.before.innerHTML = "";
        }
        if (flag != 'read') submit();
    } else {
        scwin.go_Stock(9, code, changeNameFlag);
    }
};



//오리지널 문자열을 Hex로 인코딩하는 함수
/**
 * @method
 * @name StringToHex4
 * @description desc
 * @param {string} OriginalString desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.StringToHex4 = function(OriginalString) {
    var ReturnString = "";
    for (var i = 0; i < OriginalString.length; i++) {
        var tmp = "0000" + (parseInt(OriginalString.charCodeAt(i)).toString(16));
        var tmp2 = tmp.substring(tmp.length - 4);
        ReturnString += tmp2;
    }
    return ReturnString.toUpperCase();
};


/*
 * Hex 문자열을 오리지널 문자열로 복원하는 함수
 */
/**
 * @method
 * @name Hex4ToStr
 * @description desc
 * @param {string} encode_data desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.Hex4ToStr = function(encode_data) {
    var newData = "";
    var iNo = 0;
    for (var i = 0; i < encode_data.length / 4; i++) {
        var str = encode_data.substr(iNo, 4);
        var iNum = parseInt('0x' + str);
        var strChar = String.fromCharCode(iNum);
        newData += strChar;
        iNo = iNo + 4;
    }
    return newData;
};
